style.css:
@-moz-document domain("web.whatsapp.com") {
/* ─── VARIABLES ──────────────────────────────────────────── */
  :root {
    --bg-base:        #0e0e10;
    --bg-surface:     #141416;
    --bg-elevated:    #1c1c1f;
    --bg-hover:       #222226;
    --bg-active:      #28282d;

    --accent:         #8b5cf6;
    --accent-dim:     #6d3fd6;
    --accent-glow:    rgba(139, 92, 246, 0.15);
    --accent-bubble:  #5b3dbf;

    --text-primary:   #e8e8ec;
    --text-secondary: #8a8a96;
    --text-muted:     #55555f;
    --text-on-accent: #ffffff;

    --border:         rgba(255,255,255,0.06);
    --border-strong:  rgba(255,255,255,0.10);

    --bubble-in:      #1e1e23;
    --bubble-out:     #2a1f4e;

    --shadow:         0 2px 12px rgba(0,0,0,0.5);
    --radius-sm:      6px;
    --radius-md:      10px;
    --radius-lg:      18px;
  }

  /* ─── GLOBAL RESET ───────────────────────────────────────── */
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--bg-active) transparent;
  }
  *::-webkit-scrollbar { width: 4px; height: 4px; }
  *::-webkit-scrollbar-track { background: transparent; }
  *::-webkit-scrollbar-thumb { background: var(--bg-active); border-radius: 99px; }

  body, #app, #startup {
    background-color: var(--bg-base) !important;
    color: var(--text-primary) !important;
  }

  /* ─── SIDEBAR (left panel) ───────────────────────────────── */
  #side,
  [data-testid="chat-list-header"],
  ._ak8l, ._ak8m {
    background-color: var(--bg-surface) !important;
    border-right: 1px solid var(--border) !important;
  }

  header[data-testid="chatlist-header"],
  [data-testid="chatlist-header"] {
    background-color: var(--bg-surface) !important;
    border-bottom: 1px solid var(--border) !important;
  }

  [data-testid="cell-frame-container"],
  ._ak72, ._ak71 {
    background-color: transparent !important;
    border-bottom: 1px solid var(--border) !important;
    transition: background 0.15s ease;
  }
  [data-testid="cell-frame-container"]:hover,
  ._ak72:hover {
    background-color: var(--bg-hover) !important;
  }
  [aria-selected="true"][data-testid="cell-frame-container"],
  ._ak72._ak73 {
    background-color: var(--bg-active) !important;
    border-left: 3px solid var(--accent) !important;
  }

  [data-testid="cell-frame-title"],
  ._ak8q, ._ao3e {
    color: var(--text-primary) !important;
    font-weight: 500 !important;
  }
  [data-testid="cell-frame-secondary"],
  ._ao3f, ._ak8r {
    color: var(--text-secondary) !important;
    font-size: 12.5px !important;
  }

  [data-testid="icon-unread-count"],
  ._ahlm, ._ahln {
    background-color: var(--accent) !important;
    color: var(--text-on-accent) !important;
  }

  /* ─── SEARCH BAR ─────────────────────────────────────────── */
  [data-testid="search-bar-container"],
  ._ak-l {
    background-color: var(--bg-surface) !important;
    padding: 6px 12px !important;
  }
  [data-testid="search-bar"],
  [data-testid="search-input"],
  ._ak-m {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border) !important;
    border-radius: var(--radius-lg) !important;
    color: var(--text-primary) !important;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
  }
  [data-testid="search-input"]:focus-within,
  ._ak-m:focus-within {
    border-color: var(--accent) !important;
    box-shadow: 0 0 0 3px var(--accent-glow) !important;
  }
  [data-testid="search-input"] input,
  ._ak-m input {
    color: var(--text-primary) !important;
    background: transparent !important;
  }
  [data-testid="search-input"] input::placeholder {
    color: var(--text-muted) !important;
  }

  /* ─── MAIN CHAT PANEL ────────────────────────────────────── */
  #main {
    background-color: var(--bg-base) !important;
  }

  [data-testid="conversation-panel-wrapper"],
  ._ak-o, .copyable-area {
    background-color: var(--bg-base) !important;
  }

  [data-testid="conversation-header"],
  ._ak-r, header._amq8 {
    background-color: var(--bg-surface) !important;
    border-bottom: 1px solid var(--border) !important;
    box-shadow: none !important;
  }
  [data-testid="conversation-header"] [data-testid="conversation-info-header-chat-title"],
  ._amq8 ._ao3e {
    color: var(--text-primary) !important;
    font-weight: 600 !important;
  }
  [data-testid="conversation-header"] span[title],
  ._amq8 span[title] {
    color: var(--text-secondary) !important;
    font-size: 12px !important;
  }

  /* ─── MESSAGES ───────────────────────────────────────────── */
  [data-testid="msg-container"] .message-in .copyable-text,
  ._akbu, .message-in ._amjw {
    background-color: var(--bubble-in) !important;
    border-radius: 0 var(--radius-lg) var(--radius-lg) var(--radius-lg) !important;
    box-shadow: var(--shadow) !important;
    color: var(--text-primary) !important;
  }

  [data-testid="msg-container"] .message-out .copyable-text,
  .message-out ._amjw {
    background-color: var(--bubble-out) !important;
    border-radius: var(--radius-lg) 0 var(--radius-lg) var(--radius-lg) !important;
    box-shadow: var(--shadow) !important;
    color: var(--text-primary) !important;
  }

  ._ao3e, .selectable-text, .copyable-text span {
    color: var(--text-primary) !important;
  }

  [data-testid="msg-meta"],
  ._ak-5, ._amjx {
    color: var(--text-muted) !important;
    font-size: 11px !important;
  }

  [data-testid="msg-dblcheck"],
  [data-icon="msg-dblcheck-ack"] {
    color: var(--accent) !important;
    fill: var(--accent) !important;
  }

  [data-testid="conv-time-divider"] div,
  ._amk6 {
    background-color: var(--bg-elevated) !important;
    color: var(--text-muted) !important;
    border-radius: var(--radius-md) !important;
    border: 1px solid var(--border) !important;
    font-size: 11.5px !important;
  }

  [data-testid="quoted-message"],
  ._amk8 {
    background-color: var(--bg-active) !important;
    border-left: 3px solid var(--accent) !important;
    border-radius: var(--radius-sm) !important;
  }

  /* ─── INPUT BAR ──────────────────────────────────────────── */
  footer[data-testid="conversation-compose-box-input"],
  footer._ak-r,
  ._ak-r footer {
    background-color: var(--bg-surface) !important;
    border-top: 1px solid var(--border) !important;
  }

  [data-testid="conversation-compose-box"],
  ._ak1r {
    background-color: var(--bg-surface) !important;
  }

  [data-testid="conversation-compose-box"] [contenteditable="true"],
  ._ak1s div[contenteditable] {
    background-color: var(--bg-elevated) !important;
    border-radius: var(--radius-lg) !important;
    color: var(--text-primary) !important;
    border: 1px solid var(--border) !important;
    padding: 10px 14px !important;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
  }
  [data-testid="conversation-compose-box"] [contenteditable="true"]:focus,
  ._ak1s div[contenteditable]:focus {
    border-color: var(--accent) !important;
    box-shadow: 0 0 0 3px var(--accent-glow) !important;
    outline: none !important;
  }

  [data-testid="send"],
  [data-testid="compose-btn-send"] {
    background-color: var(--accent) !important;
    border-radius: 50% !important;
    transition: background 0.2s ease, box-shadow 0.2s ease !important;
  }
  [data-testid="send"]:hover,
  [data-testid="compose-btn-send"]:hover {
    background-color: var(--accent-dim) !important;
    box-shadow: 0 0 0 4px var(--accent-glow) !important;
  }

  [data-testid="compose-extra-action"],
  ._ak1t button {
    color: var(--text-secondary) !important;
    transition: color 0.15s ease;
  }
  [data-testid="compose-extra-action"]:hover,
  ._ak1t button:hover {
    color: var(--accent) !important;
  }

  [data-testid="emoji-picker"],
  ._ak1l {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border-strong) !important;
    box-shadow: var(--shadow) !important;
    border-radius: var(--radius-md) !important;
  }

  /* ─── ICONS & SVGs ───────────────────────────────────────── */
  [data-testid="search"] span svg,
  [data-testid="menu"] span svg,
  [data-testid="new-chat-btn"] span svg,
  ._ak7m span[data-icon] svg {
    color: var(--text-secondary) !important;
    fill: var(--text-secondary) !important;
    transition: color 0.15s, fill 0.15s;
  }
  [data-testid="search"]:hover span svg,
  [data-testid="menu"]:hover span svg,
  [data-testid="new-chat-btn"]:hover span svg {
    color: var(--accent) !important;
    fill: var(--accent) !important;
  }

  /* ─── PROFILE / INFO PANEL ───────────────────────────────── */
  [data-testid="contact-info-drawer"],
  ._ak-s {
    background-color: var(--bg-surface) !important;
    border-left: 1px solid var(--border) !important;
  }

  /* ─── MODALS & DROPDOWNS ─────────────────────────────────── */
  [role="dialog"],
  ._ak-t {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border-strong) !important;
    border-radius: var(--radius-md) !important;
    box-shadow: 0 8px 32px rgba(0,0,0,0.6) !important;
  }

  [role="menu"],
  ._ajv8 {
    background-color: var(--bg-elevated) !important;
    border: 1px solid var(--border-strong) !important;
    border-radius: var(--radius-md) !important;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5) !important;
  }
  [role="menuitem"],
  ._ajv9 {
    color: var(--text-primary) !important;
    transition: background 0.1s ease;
  }
  [role="menuitem"]:hover,
  ._ajv9:hover {
    background-color: var(--bg-hover) !important;
    color: var(--accent) !important;
  }

  /* ─── AVATAR ─────────────────────────────────────────────── */
  [data-testid="avatar"] img,
  ._ak71 img {
    border-radius: 50%;
    box-shadow: 0 0 0 2px var(--bg-surface), 0 0 0 3px var(--border) !important;
  }

  /* ─── LINKS ──────────────────────────────────────────────── */
  a {
    color: var(--accent) !important;
    text-decoration: none !important;
  }
  a:hover {
    text-decoration: underline !important;
  }

  /* ─── LOADING ────────────────────────────────────────────── */
  [data-testid="startup-container"] {
    background-color: var(--bg-base) !important;
  }
  [data-testid="startup-logo"] svg path {
    fill: var(--accent) !important;
  }
}
